### Step 2: Tidal acceleration correction (`src/deltat/mod.rs`)

```rust
fn adjust_for_tidacc(ans: f64, y: f64, tid_acc: f64, tid_acc0: f64, adjust_after_1955: bool) -> f64 {
    if y < 1955.0 || adjust_after_1955 {
        let b = y - 1955.0;
        ans + (-0.000091) * (tid_acc - tid_acc0) * b * b
    } else {
        ans
    }
}
```

### Step 3: Tidal acceleration resolver

Resolves effective tidal acceleration from `EphemerisConfig`. Maps to the C `swi_get_tid_acc` logic but stateless.

```rust
fn resolve_tidal_acceleration(config: &EphemerisConfig) -> f64 {
    if let Some(ta) = config.tidal_acceleration {
        if ta != TIDAL_AUTOMATIC {
            return ta;
        }
    }
    // Determine from ephemeris source
    // Moshier → DE404; JPL/Swiss → need denum from file (not yet implemented)
    if config.jpl_filename.is_some() {
        TIDAL_DEFAULT  // placeholder until JPL file reading lands
    } else if config.ephe_path.is_some() {
        TIDAL_DEFAULT  // placeholder until Swiss ephemeris file reading lands
    } else {
        TIDAL_DE404    // Moshier backend
    }
}
```

### Step 4: Bessel 4th-order interpolation for tabulated data

This is the most complex function. Must reproduce the C boundary handling exactly — graceful degradation from 4th to 1st order at table edges.

```rust
fn deltat_aa(tjd: f64, tid_acc: f64) -> f64 {
    let tabsiz = data::TABSIZ;
    let tabend = data::TABSTART as f64 + tabsiz as f64 - 1.0;
    let y_tab = 2000.0 + (tjd - 2451544.5) / 365.25;  // NOTE: midnight JD, not J2000

    if y_tab <= tabend {
        // --- Bessel interpolation within table ---
        let p_int = y_tab.floor();
        let iy = (p_int - data::TABSTART as f64) as usize;
        let p = y_tab - p_int;

        // Zeroth order
        let mut ans = data::DT[iy];

        // First order
        if iy + 1 >= tabsiz { /* done */ }
        else {
            ans += p * (data::DT[iy + 1] - data::DT[iy]);

            // Guard: need iy >= 1 AND iy + 2 < tabsiz for 2nd differences
            if iy >= 1 && iy + 2 < tabsiz {
                // First differences with zero-padding for out-of-range
                let mut d = [0.0_f64; 5];
                let k_start = iy as i32 - 2;
                for i in 0..5 {
                    let k = (k_start + i as i32) as i32;
                    if k >= 0 && (k + 1) < tabsiz as i32 {
                        d[i] = data::DT[(k + 1) as usize] - data::DT[k as usize];
                    }
                }
                // Second differences
                for i in 0..4 { d[i] = d[i + 1] - d[i]; }
                let mut b = 0.25 * p * (p - 1.0);
                ans += b * (d[1] + d[2]);

                // Third differences
                if iy + 2 < tabsiz {
                    for i in 0..3 { d[i] = d[i + 1] - d[i]; }
                    b *= 2.0 / 3.0;
                    ans += (p - 0.5) * b * d[1];

                    // Fourth differences
                    if iy >= 2 && iy + 3 <= tabsiz {
                        for i in 0..2 { d[i] = d[i + 1] - d[i]; }
                        b = 0.125 * b * (p + 1.0) * (p - 2.0);
                        ans += b * (d[0] + d[1]);
                    }
                }
            }
        }

        ans = adjust_for_tidacc(ans, y_tab, tid_acc, TIDAL_26, false);
        ans / 86400.0
    } else {
        // --- Future extrapolation ---
        // (see Step 7)
    }
}
```

Key boundary behavior: iy=0 → 1st order only; iy=1 → 2nd order; iy≥2 && iy≤tabsiz-4 → full 4th order; degrading again near end.

