### Step 6: Historical model — Stephenson1997

Linear interpolation in dt97[] table (50-year steps, -500 to 1600), with parabolic extrapolation + 100-year blend for Y < -500.

```rust
fn deltat_stephenson_morrison_1997(tjd: f64, tid_acc: f64) -> f64 {
    let y = 2000.0 + (tjd - J2000) / 365.25;  // Julian year

    if y < -500.0 {
        let b = (y - 1735.0) * 0.01;
        let mut ans = -20.0 + 35.0 * b * b;
        ans = adjust_for_tidacc(ans, y, tid_acc, TIDAL_26, false);

        if y >= -600.0 {
            // 100-year blend to match table start
            let ans2 = adjust_for_tidacc(DT97[0] as f64, -500.0, tid_acc, TIDAL_26, false);
            let b3 = (-500.0 - 1735.0) * 0.01;
            let ans3 = adjust_for_tidacc(-20.0 + 35.0 * b3 * b3, y, tid_acc, TIDAL_26, false);
            let dd = ans3 - ans2;
            let b_blend = (y - (-600.0)) * 0.01;
            ans -= dd * b_blend;
        }
        ans / 86400.0
    } else {
        // -500 <= Y < 1600: linear interpolation
        let iy = ((y.floor() - TAB97_START as f64) / TAB97_STEP as f64) as usize;
        let dd = (y - (TAB97_START as f64 + TAB97_STEP as f64 * iy as f64)) / TAB97_STEP as f64;
        let mut ans = DT97[iy] + (DT97[iy + 1] - DT97[iy]) * dd;
        ans = adjust_for_tidacc(ans, y, tid_acc, TIDAL_26, false);
        ans / 86400.0
    }
}
```

### Step 7: Historical model — StephensonMorrison2004

Linear interpolation in dt2[] (100-year steps, -1000 to 1600). Note the mixed-year bug: outer routing uses Gregorian Y, but table indexing uses Julian year with base JD 2451557.5.

```rust
fn deltat_stephenson_morrison_2004(tjd: f64, tid_acc: f64) -> f64 {
    let y_greg = 2000.0 + (tjd - J2000) / 365.2425;

    if y_greg < -1000.0 {
        let mut ans = deltat_longterm_morrison_stephenson(tjd);
        ans = adjust_for_tidacc(ans, y_greg, tid_acc, TIDAL_26, false);

        if y_greg >= -1100.0 {
            // 100-year blend
            let ans2 = adjust_for_tidacc(DT2[0], -1000.0, tid_acc, TIDAL_26, false);
            let tjd0 = (-1000.0 - 2000.0) * 365.2425 + J2000;
            let ans3 = deltat_longterm_morrison_stephenson(tjd0);
            let ans3 = adjust_for_tidacc(ans3, y_greg, tid_acc, TIDAL_26, false);
            let dd = ans3 - ans2;
            let b = (y_greg - (-1100.0)) * 0.01;
            ans -= dd * b;
        }
        ans / 86400.0
    } else {
        // -1000 to 1600: linear interp using JULIAN year (mixed-year bug, reproduce exactly)
        let y_jul = 2000.0 + (tjd - 2451557.5) / 365.25;
        let iy = ((y_jul.floor() - TAB2_START as f64) / TAB2_STEP as f64) as usize;
        let dd = (y_jul - (TAB2_START as f64 + TAB2_STEP as f64 * iy as f64)) / TAB2_STEP as f64;
        let mut ans = DT2[iy] + (DT2[iy + 1] - DT2[iy]) * dd;
        ans = adjust_for_tidacc(ans, y_greg, tid_acc, TIDAL_26, false);
        ans / 86400.0
    }
}
```

