### Step 9: Historical model — StephensonEtc2016 + long-term parabola

Cubic spline lookup in dtcf16, with parabolic extrapolation before -720 and after 2016.

```rust
fn deltat_longterm_morrison_stephenson(tjd: f64) -> f64 {
    let y = 2000.0 + (tjd - J2000) / 365.2425;
    let u = (y - 1820.0) / 100.0;
    -20.0 + 32.0 * u * u  // seconds
}

fn deltat_stephenson_etc_2016(tjd: f64, tid_acc: f64) -> f64 {
    let y = 2000.0 + (tjd - J2000) / 365.2425;

    // Search spline table
    let mut dt = None;
    for row in &DTCF16 {
        if tjd < row[0] { break; }
        if tjd < row[1] {
            let t = (tjd - row[0]) / (row[1] - row[0]);
            dt = Some(row[2] + row[3] * t + row[4] * t * t + row[5] * t * t * t);
            break;
        }
    }

    let dt = match dt {
        Some(v) => v,
        None if y < -720.0 => {
            let t = (y - 1825.0) / 100.0;
            -320.0 + 32.5 * t * t - 179.7337208
        }
        None => {
            // Future (after last spline segment)
            let t = (y - 1825.0) / 100.0;
            -320.0 + 32.5 * t * t + 269.4790417
        }
    };

    let dt = adjust_for_tidacc(dt, y, tid_acc, TIDAL_STEPHENSON_2016, true);
    dt / 86400.0
}
```

### Step 10: Future extrapolation in `deltat_aa`

Two branches based on active model. The 100-year transition blends the formula into the last table value.

```rust
// Inside deltat_aa, when y_tab > tabend:
fn future_extrapolation(y_tab: f64, tabend: f64, tid_acc: f64, model: DeltaTModel) -> f64 {
    let tabsiz = data::TABSIZ;
    let (mut ans, ans2) = if model == DeltaTModel::StephensonEtc2016 && y_tab < 2500.0 {
        let b = y_tab - 2000.0;
        let a = b * b * b * 121.0 / 30000000.0 + b * b / 1250.0 + b * 521.0 / 3000.0 + 64.0;
        let b2 = tabend - 2000.0;
        let a2 = b2 * b2 * b2 * 121.0 / 30000000.0 + b2 * b2 / 1250.0 + b2 * 521.0 / 3000.0 + 64.0;
        (a, a2)
    } else if model == DeltaTModel::StephensonEtc2016 {
        let b = 0.01 * (y_tab - 2000.0);
        (b * b * 32.5 + 42.5, 0.0)  // no transition for Y >= 2500
    } else {
        let b = 0.01 * (y_tab - 1820.0);
        let a = -20.0 + 31.0 * b * b;
        let b2 = 0.01 * (tabend - 1820.0);
        let a2 = -20.0 + 31.0 * b2 * b2;
        (a, a2)
    };

    // 100-year transition blend
    if y_tab <= tabend + 100.0 && !(model == DeltaTModel::StephensonEtc2016 && y_tab >= 2500.0) {
        let ans3 = data::DT[tabsiz - 1];
        let dd = ans2 - ans3;
        ans += dd * (y_tab - (tabend + 100.0)) * 0.01;
    }

    ans / 86400.0
}
```

### Step 11: Main dispatcher + DeltaT impl

```rust
pub fn calc_deltat(tjd: f64, config: &EphemerisConfig) -> f64 {
    let model = config.astro_models.delta_t;
    let tid_acc = resolve_tidal_acceleration(config);
    let y = 2000.0 + (tjd - J2000) / 365.25;
    let y_greg = 2000.0 + (tjd - J2000) / 365.2425;

    match model {
        DeltaTModel::StephensonEtc2016 if tjd < 2435108.5 => {
            let mut dt = deltat_stephenson_etc_2016(tjd, tid_acc);
            if tjd >= 2434108.5 {
                dt += (1.0 - (2435108.5 - tjd) / 1000.0) * 0.6610218 / 86400.0;
            }
            dt
        }
        DeltaTModel::EspenakMeeus2006 if tjd < 2317746.13090277789 => {
            deltat_espenak_meeus_1620(tjd, tid_acc)
        }
        DeltaTModel::StephensonMorrison2004 if y < 1620.0 => {
            if y < 1600.0 {
                deltat_stephenson_morrison_2004(tjd, tid_acc)
            } else {
                // 1600-1620 linear bridge
                let dd = (y - 1600.0) / 20.0;
                let ans = DT2[26] as f64 + dd * (DT[0] - DT2[26] as f64);
                let ans = adjust_for_tidacc(ans, y_greg, tid_acc, TIDAL_26, false);
                ans / 86400.0
            }
        }
        DeltaTModel::Stephenson1997 if y < 1620.0 => {
            if y < 1600.0 {
                deltat_stephenson_morrison_1997(tjd, tid_acc)
            } else {
                // 1600-1620 linear bridge
                let dd = (y - 1600.0) / 20.0;
                let ans = DT97[42] as f64 + dd * (DT[0] - DT97[42] as f64);
                let ans = adjust_for_tidacc(ans, y_greg, tid_acc, TIDAL_26, false);
                ans / 86400.0
            }
        }
        DeltaTModel::StephensonMorrison1984 if y < 1620.0 => {
            let ans = if y >= 948.0 {
                let b = 0.01 * (y - 2000.0);
                (23.58 * b + 100.3) * b + 101.6
            } else {
                let b = 0.01 * (y - 2000.0) + 3.75;
                35.0 * b * b + 40.0
            };
            ans / 86400.0
        }
        _ if y >= 1620.0 => {
            deltat_aa(tjd, tid_acc, model)
        }
        _ => 0.0,
    }
}

impl DeltaT for Ephemeris {
    fn delta_t(&self, jd_ut: JdUt1) -> f64 {
        calc_deltat(jd_ut.0, &self.config)
    }
}
```

